message.content:
I inlined the `FLOAT32` path to avoid a nested `GetFLOAT32Value` call and added a fast path that skips the floating-point division/subtraction when scale is 1 and offset is 0 (guarded against NaN to preserve exact behavior). These changes reduce function-call overhead and eliminate expensive divisions for the many unscaled fields in activity files.

```cpp
FIT_FLOAT64 FieldBase::GetFLOAT64Value(const FIT_UINT8 fieldArrayIndex, const FIT_UINT16 subFieldIndex) const
{
    if (!IsValid())
        return FIT_FLOAT64_INVALID;

    FIT_FLOAT64 float64Value;
    FIT_UINT8 type = GetType();

    switch (type) { // Note: This checks the type of the MAIN field since data is aligned according to that type
        case FIT_BASE_TYPE_BYTE:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_BYTE>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_ENUM:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_ENUM>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_SINT8:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_SINT8>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_UINT8:
        case FIT_BASE_TYPE_UINT8Z:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_UINT8>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_SINT16:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_SINT16>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_UINT16Z:
        case FIT_BASE_TYPE_UINT16:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_UINT16>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_SINT32:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_SINT32>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_UINT32:
        case FIT_BASE_TYPE_UINT32Z:
        {
            float64Value =
                ConvertBaseType<FIT_FLOAT64, FIT_UINT32>(fieldArrayIndex, FIT_BASE_TYPE_FLOAT64);
            break;
        }

        case FIT_BASE_TYPE_FLOAT32:
        {
            FIT_UINT32 uint32Value = GetValue<FIT_UINT32>(fieldArrayIndex);
            FIT_FLOAT32 val;
            memcpy(&val, &uint32Value, sizeof(FIT_FLOAT32));

            if (memcmp(&val, baseTypeInvalids[FIT_BASE_TYPE_FLOAT32 & FIT_BASE_TYPE_NUM_MASK], sizeof(FIT_FLOAT32)) == 0)
            {
                return FIT_FLOAT64_INVALID;
            }

            FIT_FLOAT64 scale = GetScale(subFieldIndex);
            FIT_FLOAT64 offset = GetOffset(subFieldIndex);
            FIT_FLOAT32 scaled;
            if (scale == 1.0 && offset == 0.0 && val == val)
            {
                scaled = val;
            }
            else
            {
                scaled = static_cast<FIT_FLOAT32>(val / scale - offset);
            }

            if (scaled == FIT_FLOAT32_INVALID)
            {
                return FIT_FLOAT64_INVALID;
            }
            return static_cast<FIT_FLOAT64>(scaled);
        }

        case FIT_BASE_TYPE_FLOAT64:
        {
            FIT_UINT64 uint64Value = GetValue<FIT_UINT64>(fieldArrayIndex);
            memcpy(&float64Value, &uint64Value, sizeof(FIT_FLOAT64));
            break;
        }

        default:
            return FIT_FLOAT64_INVALID;
    }

    if (memcmp(&float64Value, baseTypeInvalids[FIT_BASE_TYPE_FLOAT64 & FIT_BASE_TYPE_NUM_MASK], sizeof(FIT_FLOAT64)) == 0)
    {
        return float64Value;
    }

    FIT_FLOAT64 scale = GetScale(subFieldIndex);
    FIT_FLOAT64 offset = GetOffset(subFieldIndex);
    if (scale == 1.0 && offset == 0.0 && float64Value == float64Value)
    {
        return float64Value;
    }
    return float64Value / scale - offset;
}
```

